// Pull product/POD metadata for every Etsy listing referenced in the order's
// line items. Skips early if the order is empty or already routed.
const row = $input.first().json;
if (!row) throw new Error('Order not found');

const transactions = Array.isArray(row.line_items) ? row.line_items : [];
const etsyListingIds = [...new Set(transactions.map(t => String(t.listing_id)).filter(Boolean))];

return [{ json: { ...row, transactions, etsyListingIds } }];

// Decide whether this order needs POD routing, and if so, build the
// provider-specific payload. Soft-exits with status='skipped' when the
// order has no POD line items, the shop has no provider configured, or any
// product is missing pod_metadata.
const order = $('Prep').first().json;
const mappingRows = $input.all().map(i => i.json);
const byListing = Object.fromEntries(mappingRows.map(r => [String(r.etsy_listing_id), r]));

const podLines = order.transactions.filter(t => byListing[String(t.listing_id)]?.kind === 'pod');
if (!podLines.length) {
  return [{ json: { _action: 'noop', order_id: order.order_id, reason: 'no POD line items' } }];
}
if (!order.pod_provider || !order.pod_shop_id) {
  return [{ json: { _action: 'pending', order_id: order.order_id, reason: 'shop has no pod_provider/pod_shop_id configured' } }];
}
const missingMeta = podLines.filter(t => !byListing[String(t.listing_id)]?.pod_metadata);
if (missingMeta.length) {
  return [{ json: { _action: 'pending', order_id: order.order_id, reason: `pod_metadata missing for listings ${missingMeta.map(t => t.listing_id).join(',')}` } }];
}

// Address from the Etsy receipt.
const r = order.raw || {};
const address = {
  first_name: r.name?.split(' ')?.[0] || r.first_line || 'Customer',
  last_name:  r.name?.split(' ').slice(1).join(' ') || '',
  email:      r.buyer_email || r.email || null,
  phone:      r.buyer_phone || '',
  country:    r.country_iso || r.country_name || 'US',
  region:     r.state || '',
  address1:   r.first_line || '',
  address2:   r.second_line || '',
  city:       r.city || '',
  zip:        r.zip || ''
};

let url, headers, body;
if (order.pod_provider === 'printify') {
  const apiKey = process.env.PRINTIFY_API_KEY;
  if (!apiKey) return [{ json: { _action: 'pending', order_id: order.order_id, reason: 'PRINTIFY_API_KEY not set' } }];
  url = `https://api.printify.com/v1/shops/${order.pod_shop_id}/orders.json`;
  headers = { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' };
  body = {
    external_id: `etsy-${order.etsy_order_id}`,
    label: order.shop_name,
    line_items: podLines.map(t => {
      const meta = byListing[String(t.listing_id)].pod_metadata;
      return { product_id: meta.product_id, variant_id: meta.variant_id, quantity: t.quantity || 1 };
    }),
    shipping_method: 1,
    send_shipping_notification: false,
    address_to: address
  };
} else if (order.pod_provider === 'printful') {
  const apiKey = process.env.PRINTFUL_API_KEY;
  if (!apiKey) return [{ json: { _action: 'pending', order_id: order.order_id, reason: 'PRINTFUL_API_KEY not set' } }];
  url = 'https://api.printful.com/orders';
  headers = { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'X-PF-Store-Id': String(order.pod_shop_id) };
  body = {
    external_id: `etsy-${order.etsy_order_id}`,
    recipient: {
      name:    [address.first_name, address.last_name].filter(Boolean).join(' '),
      address1: address.address1,
      address2: address.address2,
      city:    address.city,
      state_code: address.region,
      country_code: address.country,
      zip:     address.zip,
      phone:   address.phone,
      email:   address.email
    },
    items: podLines.map(t => {
      const meta = byListing[String(t.listing_id)].pod_metadata;
      return { variant_id: meta.variant_id, quantity: t.quantity || 1, files: meta.files || [] };
    })
  };
} else {
  return [{ json: { _action: 'pending', order_id: order.order_id, reason: `unsupported pod_provider '${order.pod_provider}'` } }];
}

return [{ json: { _action: 'send', order_id: order.order_id, provider: order.pod_provider, url, headers, body } }];

// Normalise the provider response.
const sent = $('Build Provider Payload').first().json;
const res  = $input.first().json;
const providerOrderId = res.id || res.result?.id || res.order_id || null;
const error = providerOrderId ? null : (res.error || res.errors || JSON.stringify(res).slice(0, 500));
return [{ json: {
  order_id: sent.order_id,
  provider: sent.provider,
  pod_order_id: providerOrderId ? String(providerOrderId) : null,
  status: providerOrderId ? 'pod_routed' : 'pod_failed',
  error
} }];
